    status: "geprueft",
    pruefer: "Paket E (Welle 1, Prüfung am Original) · Zweitprüfung TODO-E6",
    klasse: "B",
    notiz: "Flach- und Hügelland; PVGIS-Mittel ~1.199 kWh/kWp, Rechenwert bewusst darunter (eigener Abschlag wie DE).",
  },
