    gueltigAb: null,
    gueltigBis: null,
    status: "zu_pruefen",
    pruefer: OFFEN,
    klasse: "A",
    notiz: "Wie Regionalseiten (z. B. oberoesterreich.js). Fördercall-Termine gehören in die Termin-Daten (FRI).",
  },
];

const MODUL = {
  name: "at",
