// src/app/(stamm)/kommunen/widmungskit/page.js – AT-Widmungskit (Welle 3, Paket B8)
//
// Ablauf, beteiligte Stellen und Prüfpunkte der Umwidmung für einen Solarpark je österreichischem Bundesland –
